+/** Dispatch a target-qualified tracking event without collapsing it to the relation trait. */
+export function setPairTrackingEvent(
+    world: World,
+    entity: Entity,
+    trait: Trait,
+    target: Entity,
+    eventType: 'add' | 'remove'
+) {
+    const ctx = world[$internal];
+    const data = getTraitInstance(ctx.traitInstances, trait);
+    if (!data) return;
+
+    for (const query of data.trackingQueries) {
+        if (!query.trackingGroups.some((group) => group.pairs.length)) continue;
+        const match = query.checkTracking(world, entity, eventType, data.generationId, data.bitflag, target);
+        if (match) query.add(entity);
+        else query.remove(world, entity);
+    }
+}
